    function renderMissing(list){const entries=Array.isArray(list)&&list.length?list:list?.requiredBeforeHardwareSelection||missingDefaults;$('[data-auto-missing]').innerHTML=(list&&!Array.isArray(list)?'<li><strong>Catalog gaps:</strong> '+fmt(list.motorSpeedMissing,0)+' / '+fmt(list.motorCount,0)+' motors missing speed; '+fmt(list.gearboxEfficiencyMissing,0)+' gearbox efficiencies, '+fmt(list.gearboxInputInertiaMissing,0)+' input inertias and '+fmt(list.gearboxOutputInertiaMissing,0)+' output inertias missing.</li>':'')+entries.map(x=>'<li>'+esc(typeof x==='string'?x:x.message||x.description||x.name||JSON.stringify(x))+'</li>').join('');}
    function bestCase(c,kind){return tested(c.pymunk?.[kind])?c.pymunk[kind]:c.analytical?.[kind];}
